import React, { useState, useEffect } from 'react';
import { ref, onValue } from 'firebase/database';
import { db } from '../firebase';
import { Link } from 'react-router-dom';

function SeriesList() {
  const [series, setSeries] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const seriesRef = ref(db, 'series');
    const unsubscribe = onValue(seriesRef, (snapshot) => {
      const data = snapshot.val();
      if (data) {
        const seriesList = Object.entries(data).map(([id, seriesData]) => ({
          id,
          ...seriesData
        }));
        setSeries(seriesList);
      } else {
        setSeries([]);
      }
      setLoading(false);
    });

    return () => unsubscribe();
  }, []);

  if (loading) {
    return (
      <div className="text-center">
        <p className="text-xl">Yükleniyor...</p>
      </div>
    );
  }

  return (
    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
      {series.map(seriesItem => (
        <Link
          key={seriesItem.id}
          to={`/series/${seriesItem.id}`}
          className="bg-white rounded-lg shadow-md p-6 hover:shadow-lg transition duration-200"
        >
          <h3 className="text-xl font-bold text-purple-600 mb-2">{seriesItem.title}</h3>
          <div className="space-y-2 text-gray-600">
            <p>Sezon: {seriesItem.currentSeason}/{seriesItem.totalSeasons}</p>
            <p>Bölüm: {seriesItem.currentEpisode}/{seriesItem.episodesPerSeason}</p>
            <p className="text-sm">
              {seriesItem.watchingTogether ? 'Birlikte İzliyoruz' : 'Ayrı İzliyoruz'}
            </p>
          </div>
        </Link>
      ))}
      {series.length === 0 && (
        <div className="col-span-full text-center">
          <p className="text-xl text-gray-600">Henüz dizi eklenmemiş.</p>
          <Link
            to="/add-series"
            className="inline-block mt-4 bg-purple-600 text-white py-2 px-4 rounded-lg hover:bg-purple-700 transition duration-200"
          >
            Dizi Ekle
          </Link>
        </div>
      )}
    </div>
  );
}

export default SeriesList;
